// Patient Care Technician Practice Test 1. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items: bedside judgment, phlebotomy and EKG basics.
import {q, mix} from './q.js';
const NHA='NHA PCT Skills Builder Plus', NHAG='NHA CPCT/A Online Study Guide';
const CARE='Patient Care', COMP='Compliance, Safety, & Professional Responsibility', INF='Infection Control', PHL='Phlebotomy', EKG='EKG';

export default {
 id:'patient-care-technician-1',
 event:'Patient Care Technician',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'NHA PCT Skills Builder Plus and the NHA CPCT/A Online Study Guide',
 plan:[{area:CARE,weight:44},{area:COMP,weight:20},{area:INF,weight:12},{area:PHL,weight:14},{area:EKG,weight:10}],
 questions:mix([
  q(CARE,'A patient’s blood pressure is 128/80 lying down and 104/66 after standing for 1 minute, and he feels dizzy. What does this suggest?','Orthostatic hypotension',['Hypertensive crisis','A normal response to standing','White coat hypertension'],'B','A drop of 20 mm Hg or more systolic, or 10 or more diastolic, within a few minutes of standing is orthostatic hypotension. It raises fall risk and should be reported.',NHAG),
  q(CARE,'Which pain scale is best for a 4-year-old who cannot rate pain with numbers?','A faces rating scale',['A 0–10 numeric scale','A visual acuity chart','The Glasgow Coma Scale'],'D','Faces scales let young children point to a face matching how they feel. Numeric scales require understanding of numbers.',NHA),
  q(CARE,'A pulse oximeter reads 82% on a calm patient with no breathing difficulty and dark nail polish. What should the PCT do first?','Check the probe placement or move it',['Start high-flow oxygen immediately','Call a rapid response','Record the reading and leave'],'A','Dark nail polish, poor circulation, cold fingers and movement can cause false readings. Reposition the probe (for example, to an earlobe or a finger without polish) and recheck, then report true low readings.',NHA),
  q(CARE,'For a fingerstick blood glucose test, where should the puncture be made?','On the side of the fingertip',['In the center of the finger pad','On the fingernail bed','On the back of the hand'],'C','The side of the fingertip has fewer nerve endings and enough capillaries, making it less painful. Follow the meter’s instructions about wiping the first drop.',NHA),
  q(CARE,'Why is an incentive spirometer used after surgery?','To prevent atelectasis and pneumonia',['To measure blood oxygen','To deliver inhaled medication','To reduce incision pain'],'B','Slow, deep breaths with the spirometer keep the alveoli open. Shallow breathing after surgery can lead to collapsed lung areas and pneumonia.',NHA),
  q(CARE,'What is the purpose of sequential compression devices on a postoperative patient’s legs?','To prevent deep vein thrombosis',['To reduce leg swelling from injury','To keep the legs warm','To stop the patient from getting up'],'D','The sleeves inflate and deflate to squeeze the calves, moving blood back toward the heart and preventing clots that form with immobility.',NHA),
  q(CARE,'Which technique is used to turn a patient after spinal surgery?','Logrolling',['Having the patient pull on the side rail','Turning the shoulders first, then the hips','Sitting the patient up first'],'A','Logrolling turns the head, shoulders and hips as one unit, keeping the spine straight. It usually takes two or more staff members.',NHA),
  q(CARE,'A patient with severe shortness of breath is most comfortable in which position?','High Fowler’s',['Supine','Trendelenburg','Prone'],'C','Sitting upright (high Fowler’s) lets the diaphragm move down and the lungs expand more fully.',NHA),
  q(CARE,'Which tool assesses a patient’s risk of developing pressure injuries?','The Braden Scale',['The Glasgow Coma Scale','The APGAR score','The Morse Scale'],'B','The Braden Scale scores sensory perception, moisture, activity, mobility, nutrition and friction/shear. Lower scores mean higher risk. The Morse Scale assesses fall risk.',NHA),
  q(CARE,'Wound drainage that is thin and pink is described as:','Serosanguineous',['Serous','Purulent','Sanguineous'],'D','Serous drainage is clear, sanguineous is bloody, serosanguineous is pink (blood mixed with serum), and purulent is thick and contains pus.',NHA),
  q(CARE,'During indwelling catheter care, in which direction should the catheter be cleaned?','From the meatus outward along the tubing',['From the tubing toward the meatus','In a back-and-forth motion','Only where it enters the bag'],'A','Cleaning away from the urethral opening keeps bacteria from moving into the bladder and helps prevent catheter-associated urinary tract infections.',NHA),
  q(CARE,'An adult patient’s urine output has been 20 mL/hr for the past 2 hours. What should the PCT do?','Report it to the nurse',['Encourage the patient to drink later','Record it and check again tomorrow','Empty the bag and ignore the volume'],'C','Output below about 30 mL/hr may signal dehydration, shock or kidney problems and should be reported promptly.',NHA),
  q(CARE,'A patient who is NPO for surgery asks for water because his mouth is dry. What can the PCT offer?','Mouth care and lip moisturizer',['A small glass of water','Ice chips without asking','A cup of tea'],'B','NPO means nothing by mouth. Mouth care and lip balm relieve dryness without breaking the fast. Ask the nurse about any exceptions.',NHA),
  q(CARE,'A patient receiving continuous tube feedings must have the head of the bed raised at least how far?','30 degrees',['5 degrees','10 degrees','Flat'],'D','Keeping the head of the bed at 30 degrees or more reduces the risk of formula entering the lungs (aspiration).',NHA),
  q(CARE,'When walking a patient who has an IV, where should the IV bag be kept?','Above the IV site',['Below the IV site','At the patient’s waist','On the patient’s lap'],'A','Gravity keeps fluid flowing into the vein. If the bag is lowered below the site, blood can back up into the tubing.',NHA),
  q(CARE,'How should a gait belt be applied?','Snugly around the waist, over clothing',['Loosely around the chest','Around the patient’s hips under clothing','Around the PCT’s own waist'],'C','The belt goes around the patient’s waist over clothing, snug enough that only a few fingers fit under it. The PCT holds it with an underhand grip.',NHA),
  q(CARE,'A PCT finds a patient on the floor beside the bed. What should be done first?','Stay with the patient and call for the nurse',['Lift the patient back into bed','Help the patient walk to the bathroom','Leave to find a mechanical lift'],'B','The patient should not be moved until the nurse assesses for injury. Stay with the patient, call for help and keep them calm.',NHA),
  q(CARE,'How is a temporal artery thermometer used?','Swept across the forehead',['Placed under the tongue','Inserted into the ear canal','Held firmly in the armpit'],'D','The scanner slides across the forehead over the temporal artery and may be touched behind the ear to account for sweat.',NHA),
  q(CARE,'Which findings suggest dehydration?','Dark urine and dry mucous membranes',['Pale urine and moist lips','Weight gain and swollen ankles','A slow pulse and warm skin'],'A','Dehydration causes concentrated (dark) urine, dry mouth, thirst, poor skin turgor and a rapid pulse. Weight gain and swelling suggest fluid overload.',NHAG),
  q(CARE,'During postmortem care, why is the head elevated on a pillow?','To prevent facial discoloration',['To make the body easier to move','To keep the airway open','To show respect to visiting family'],'C','After death, blood settles in the lowest parts of the body (livor mortis). Elevating the head helps prevent facial discoloration before the family views the body.',NHA),
  q(CARE,'On an intake and output record, how are ice chips counted?','As half their volume',['As their full volume','They are not counted','As double their volume'],'B','Ice melts to about half its volume, so 200 mL of ice chips is recorded as about 100 mL of fluid intake.',NHA),
  q(CARE,'When taking an adult’s tympanic temperature, how should the ear be pulled?','Up and back',['Down and back','Straight down','Forward'],'D','Pulling the pinna up and back straightens an adult’s ear canal so the probe points at the eardrum. For young children it is pulled down and back.',NHA),
  q(COMP,'Before collecting a blood specimen, how should the PCT identify the patient?','Use two identifiers',['Ask “Are you Mr. Lee?” at the door','Check the name on the door','Use the room number'],'A','Using two identifiers, compared against the wristband and order, prevents errors. Patients should state their name rather than answer yes to a name.',NHAG),
  q(COMP,'Two PCTs discuss a patient’s diagnosis in a crowded hospital elevator. What is the problem?','It is a breach of patient confidentiality',['It is acceptable if no names are used','It is fine because both are staff','It is only a problem if the patient hears'],'C','Discussing patient information in public areas can expose protected health information to others and violates HIPAA and facility policy.',NHAG),
  q(COMP,'Where is an incident report filed after a patient fall?','With risk management, not the chart',['In the patient’s chart','In the patient’s discharge papers','With the patient’s insurance company'],'B','Incident reports are internal quality documents. The chart records the facts of the fall and the care given, but does not mention the incident report.',NHA),
  q(COMP,'Which task is outside a PCT’s scope and requires a registered nurse?','The admission nursing assessment',['Recording vital signs','Obtaining a 12-lead EKG','Collecting a blood specimen'],'D','PCTs collect data and perform delegated skills, but the initial assessment and nursing care planning are RN responsibilities.',NHAG),
  q(COMP,'A competent patient refuses a bath. What should the PCT do?','Respect it and tell the nurse',['Give the bath anyway','Ask the family to force the bath','Withhold the next meal'],'A','Patients have the right to refuse care. The PCT documents and reports the refusal so the nurse can follow up.',NHA),
  q(COMP,'A patient with a valid DNR order stops breathing and has no pulse. What should the PCT do?','Notify the nurse; do not start CPR',['Begin CPR immediately','Call a code blue','Apply the AED pads at once'],'C','A do-not-resuscitate order means CPR is not performed. The PCT should alert the nurse and follow facility policy.',NHA),
  q(COMP,'Where can a PCT find information on the hazards and safe handling of a cleaning chemical?','The Safety Data Sheet',['The patient’s chart','The care plan','The incident report'],'B','OSHA requires Safety Data Sheets for hazardous chemicals. They describe hazards, protective equipment, first aid and spill handling.',NHA),
  q(COMP,'A PCT notices an IV pump with a frayed power cord. What should be done?','Remove it from use, tag it and report it',['Wrap the cord in tape and keep using it','Unplug it only at night','Ignore it if the pump still works'],'D','Damaged equipment is a shock and fire hazard. It should be taken out of service, labeled and reported for repair.',NHA),
  q(COMP,'A PCT suspects a confused older patient is being neglected by her caregiver. What is required?','Report the suspicion according to policy',['Wait until there is proof','Discuss it with the caregiver first','Post about it online'],'A','Healthcare workers must report suspected abuse or neglect. Reports made in good faith are legally protected.',NHAG),
  q(COMP,'Which statement about physical restraints is correct?','They need an order and are a last resort',['They may be applied whenever a patient is restless','They can stay on without checks for a full shift','Family can request them without a provider order'],'C','Restraints need an order, the least restrictive option, frequent monitoring and regular release for care. Alternatives are tried first.',NHA),
  q(INF,'To which patients do standard precautions apply?','All patients',['Only patients with known infections','Only patients in isolation','Only surgical patients'],'B','Standard precautions treat all blood and body fluids as potentially infectious, regardless of diagnosis.',NHA),
  q(INF,'Which precautions are used for a patient with influenza?','Droplet precautions',['Airborne precautions with an N95','Contact precautions only','No extra precautions'],'D','Influenza spreads by large respiratory droplets over short distances. Droplet precautions require a mask within close range and a private room when possible.',NHA),
  q(INF,'When removing PPE, which item is removed first?','Gloves',['Gown','Mask','Goggles'],'A','Gloves are the most contaminated and are removed first, followed by goggles, gown and mask, then hand hygiene. (Some methods remove gloves with the gown.)',NHA),
  q(INF,'Which item should be kept out of the room of a patient on neutropenic precautions?','Fresh flowers',['A clean gown','A thermometer','A call light'],'C','Patients with very low white blood cell counts are vulnerable to bacteria and fungi in fresh flowers, plants and standing water.',NHA),
  q(INF,'How long should hands be rubbed together when washing with soap and water?','At least 20 seconds',['About 5 seconds','About 2 minutes','Only until the soap lathers'],'B','Rubbing all surfaces of the hands for at least 20 seconds, then rinsing fingertips down, removes most transient microorganisms.',NHA),
  q(INF,'Which action helps prevent catheter-associated urinary tract infections?','Keeping the drainage system closed',['Disconnecting the bag to empty it','Resting the bag on the floor','Lifting the bag above the bladder'],'D','A closed system keeps bacteria out. The bag is emptied from its spout, kept off the floor and kept below the bladder.',NHA),
  q(PHL,'Following the order of draw, which tube is collected right after the light blue citrate tube?','Gold or red serum tube',['Lavender EDTA tube','Gray fluoride tube','Green heparin tube'],'A','The order is blood cultures, light blue, serum (red/gold), green, lavender, then gray. This prevents additive carryover from affecting results.',NHA),
  q(PHL,'Which practice can cause a hemolyzed blood specimen?','Shaking the tube vigorously',['Gently inverting the tube','Using the correct needle size','Letting alcohol dry before puncture'],'C','Shaking, pulling hard on a syringe plunger or using a very small needle can rupture red cells, falsely raising potassium and other results.',NHA),
  q(PHL,'A blood bump forms at the site during the draw. What is the likely cause?','The needle went through the vein',['The tourniquet was too loose','The tube was underfilled','The patient fasted too long'],'B','A hematoma forms when blood leaks into the tissue, often because the needle passed through the back wall of the vein or was only partly in it.',NHA),
  q(PHL,'Which tube is used for a complete blood count?','Lavender EDTA',['Light blue citrate','Gray fluoride','Gold serum separator'],'D','EDTA prevents clotting and preserves cell shape, making it the standard tube for CBCs.',NHA),
  q(PHL,'Which tube is used for a PT/INR test?','Light blue citrate',['Lavender EDTA','Green heparin','Red plain serum'],'A','Coagulation tests use citrate tubes, which must be filled completely to keep the 9:1 blood-to-anticoagulant ratio.',NHA),
  q(PHL,'Why is chlorhexidine or iodine used instead of alcohol alone before drawing blood cultures?','To prevent skin bacteria in the culture',['To make the vein easier to see and feel','To speed up clotting','To numb the skin'],'C','Blood cultures detect bacteria in the blood, so thorough skin antisepsis is needed to prevent false-positive results from skin flora.',NHA),
  q(PHL,'A patient takes warfarin. What should the PCT do after the needle is removed?','Hold pressure longer until bleeding stops',['Apply a bandage immediately without pressure','Have the patient bend the elbow tightly','Massage the site'],'B','Anticoagulants prolong bleeding. Holding firm pressure longer prevents hematomas. Bending the arm can reopen the puncture.',NHA),
  q(EKG,'How many electrodes are used for a standard 12-lead EKG?','10',['3','5','12'],'D','Four limb electrodes and six chest electrodes create 12 views (leads) of the heart’s electrical activity.',NHA),
  q(EKG,'On standard EKG paper running at 25 mm/second, how much time does one small box represent?','0.04 seconds',['0.20 seconds','1 second','0.10 seconds'],'A','Each small box is 1 mm, or 0.04 seconds. Each large box (5 small boxes) is 0.20 seconds.',NHA),
  q(EKG,'What does the P wave on an EKG represent?','Atrial depolarization',['Ventricular depolarization','Ventricular repolarization','Atrial repolarization'],'C','The P wave is the atria contracting. The QRS complex is ventricular depolarization, and the T wave is ventricular repolarization.',NHA),
  q(EKG,'On a regular rhythm strip, there are 4 large boxes between R waves. Using the 300 method, what is the heart rate?','75 beats per minute',['60 beats per minute','100 beats per minute','150 beats per minute'],'B','Divide 300 by the number of large boxes between consecutive R waves: 300 ÷ 4 = 75.',NHA),
  q(EKG,'Before placing electrodes on a patient with very oily skin, what should be done?','Clean the skin first',['Apply lotion to the skin','Place electrodes over clothing','Use extra electrodes on each limb'],'D','Oils, lotion and sweat prevent good contact and cause artifact. Cleaning (and clipping hair if needed) improves the tracing.',NHA)
 ],71)
};
